// .  mk
// .  ll \\n[column-length]u
// .  wh -\\n[bottom-margin]u 2c-trap
// .  nr right-side 0
// ..
// .
//
// .de 2c-trap
// .  ie \\n[right-side] \{\
// .    nr right-side 0
// .    po -(\\n[column-length]u + \\n[column-gap]u)
// .    \" remove trap
